import{z as A,x as o,o as l,c as p,q as B,j as s,D as t,d as E,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"MVCC","description":"","frontmatter":{"title":"MVCC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mvcc.md","filePath":"cs/mvcc.md","lastUpdated":1791063341000}'),d={name:"cs/mvcc.md"};function c(m,a,C,V,h,S){const r=o("Mermaid");return l(),p("div",null,[a[2]||(a[2]=B('<h1 id="mvcc" tabindex="-1">MVCC <a class="header-anchor" href="#mvcc" aria-label="Permalink to &quot;MVCC&quot;">​</a></h1><div class="epigraph"><p>写出新版本而不原地覆盖；读去取自己快照里可见的那一版，读与写不必抢同一把锁。</p><footer>—— 据 Reed, Naming and Synchronization in a Decentralized Computer System, 1978；Bernstein 对多版本调度的整理</footer></div><p><a href="/cs/strict-2pl">上一课</a>用严格两阶段锁保证可串行，读也要加 S。本课不重讲锁点。缺口是：只读事务被写阻塞，或写被长查询挡住。多版本并发控制让写创建新版本，读按时间戳或快照选可见版本，读锁可以去掉或大大减弱。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2PL 的 S 与 X 不兼容，分析查询会挡住更新。缺口不是放弃隔离，而是给每个写一个版本号（事务 id、时间戳），可见性函数回答「这一读能看见哪一版」。快照隔离（SI）是广泛实现：事务开始时钉一个快照，读都来自该快照，写冲突在提交时用写集检测。</p><p><span class="marginnote">直觉类比：MVCC 像文档的「修订历史」而不是原地改原文——每次编辑追加一版，老读者仍打开自己开始看时的那一版；谁也不用等谁，只剩「你能看见哪一版」的规则。</span></p><p><span class="marginnote">SI 避免脏读、不可重复读与部分幻象，但允许写偏斜：两个事务读同一快照、写不同行，各自提交，串行下不可能同时成立。那是后课隔离级别要命名的异常。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每行带创建/删除版本。读不阻塞写；写若与未提交或快照后的版本冲突，则 abort 或等待。垃圾回收删除对所有活跃快照都不可见的旧版。本课不把 SSI（可串行快照隔离）的冲突检测写完，只锁定：版本 + 可见性是与锁并列的实现轴。</p>',9)),(l(),s(n,null,{default:t(()=>[i(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%22%5D%20--%3E%20VER%5B%22%E6%96%B0%E7%89%88%E6%9C%AC%22%5D%0A%20%20R%5B%22%E8%AF%BB%22%5D%20--%3E%20VIS%5B%22%E5%BF%AB%E7%85%A7%E5%8F%AF%E8%A7%81%E6%80%A7%22%5D%0A%20%20VER%20--%3E%20GC%5B%22%E5%9B%9E%E6%94%B6%E6%97%A7%E7%89%88%22%5D%0A%20%20VIS%20--%3E%20ISO%5B%22%E5%90%8E%E8%AF%BE%3A%20%E9%9A%94%E7%A6%BB%E7%BA%A7%E5%88%AB%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("WAL 仍记录什么变了；版本是并发的表示，不是另一种恢复。回滚可以只是标该版本不可见。索引必须指向「当前」版本或带版本的项，B+ 叶上的空间与清理成为新的代价——与"),e("a",{href:"/cs/page-slot"},"页与槽"),E("的空间回收相接。长只读快照会拖住 GC，这是 MVCC 的资源边界。")],-1)),a[5]||(a[5]=e("p",null,"写写冲突仍要检测或等待；「读不阻塞写」不等于「写不冲突」。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易把「读不阻塞写」听成「MVCC 没有冲突」。两个事务写同一行照样要检测或等待；被去掉的只是读写之间那把锁，不是所有协调。")],-1)),(l(),s(n,null,{default:t(()=>[i(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20V1%5B%22V1%20%E7%94%B1%E4%BA%8B%E5%8A%A1%2010%20%E5%88%9B%E5%BB%BA%22%5D%20--%3E%20V2%5B%22V2%20%E7%94%B1%E4%BA%8B%E5%8A%A1%2020%20%E6%9B%B4%E6%96%B0%22%5D%0A%20%20V2%20--%3E%20V3%5B%22V3%20%E7%94%B1%E4%BA%8B%E5%8A%A1%2030%20%E6%9B%B4%E6%96%B0%22%5D%0A%20%20RD%5B%22%E8%AF%BB%E8%80%85%E5%BF%AB%E7%85%A7%2025%22%5D%20--%3E%20VIS%5B%22%E5%8F%AF%E8%A7%81%E6%80%A7%E5%87%BD%E6%95%B0%E9%80%90%E7%89%88%E5%88%A4%E6%96%AD%22%5D%0A%20%20VIS%20--%3E%7C%2210%20%E5%B7%B2%E6%8F%90%E4%BA%A4%E4%B8%94%E6%97%A9%E4%BA%8E%E5%BF%AB%E7%85%A7%22%7C%20OK%5B%22V1%20%E5%8F%AF%E8%A7%81%22%5D%0A%20%20VIS%20--%3E%7C%2220%20%E4%B8%8E%2030%20%E6%99%9A%E4%BA%8E%E5%BF%AB%E7%85%A7%22%7C%20NO%5B%22V2%20%E4%B8%8E%20V3%20%E8%A2%AB%E8%B7%B3%E8%BF%87%22%5D%0A%20%20OK%20--%3E%20ANS%5B%22%E8%AF%BB%E8%80%85%E6%8B%BF%20V1%2C%20%E5%85%A8%E7%A8%8B%E6%97%A0%E9%94%81%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=B('<p><span class="marginnote">术语翻译：闩锁（latch）就是保护 B+ 树页面几纳秒的物理短锁，防两个线程同时改同一页；事务锁（lock）一持就是整个事务——名字相近，寿命差着六个数量级，混称会闹笑话。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>MVCC 不是自动可串行。SI ≠ 冲突可串行。本课也不把「无锁」写成事实：写写仍要检测，字典结构本身仍要闩锁（latch），那是物理短锁，不是 2PL 的事务锁。</p><p>只读事务可以拿一个旧快照一直读，写者前进；这是分析负载的常见配置，代价是旧版本堆积。后课默认：引擎可以锁、可以版本、可以混合（写锁 + 读快照）；用户看见的强度用隔离级别与异常来谈，而不是用内部版本号。</p><p>快照是时间上的切面，不是另一份数据库。写仍要落 WAL；版本只回答「读看见谁」，不替代提交记录。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>长快照拖住垃圾回收，是 MVCC 的空间账单，不是免费的非阻塞读。</p></li><li><p>后课用异常名字把 SI 与可串行的差额说给应用听。</p></li><li><p>2PL 让读写互斥；MVCC 用版本让读走快照。</p></li><li><p>可见性函数是隔离的实现；SI 仍可能写偏斜。</p></li><li><p>用户侧档位（读已提交、可重复读、可串行）是后课缺口。</p></li><li><p>出处：Reed, 1978；Berenson et al., 1995；Bernstein 多版本章节。</p></li></ul>',7))])}const D=A(d,[["render",c]]);export{f as __pageData,D as default};
